from solution import attach_particle


def test_zero_alone():
    assert attach_particle('0', '이/가') == '0이'


def test_zero_euro():
    assert attach_particle('0', '으로/로') == '0으로'


def test_ten():
    assert attach_particle('10', '이/가') == '10이'


def test_ten_euro():
    assert attach_particle('10', '으로/로') == '10으로'


def test_hundred():
    assert attach_particle('100', '은/는') == '100은'


def test_thousand():
    assert attach_particle('1000', '을/를') == '1000을'


def test_twenty():
