def test_ten_thousand():
    assert attach_particle('10000', '이/가') == '10000이'


def test_digit_rieul_euro():
    assert attach_particle('7', '으로/로') == '7로'
    assert attach_particle('1', '으로/로') == '1로'
    assert attach_particle('8', '으로/로') == '8로'


def test_digit_non_rieul_euro():
    assert attach_particle('3', '으로/로') == '3으로'
    assert attach_particle('6', '으로/로') == '6으로'


def test_hangul_rieul():
    assert attach_particle('서울', '으로/로') == '서울로'
    assert attach_particle('서울', '은/는') == '서울은'


def test_hangul_basic():
    assert attach_particle('책', '을/를') == '책을'
    assert attach_particle('나무', '과/와') == '나무와'
    assert attach_particle('집', '으로/로') == '집으로'


def test_vowel_digits():
    assert attach_particle('2', '이/가') == '2가'
    assert attach_particle('5', '을/를') == '5를'


def test_mixed_word_digit():
    assert attach_particle('방10', '이/가') == '방10이'
    assert attach_particle('A30', '으로/로') == 'A30으로'

